INSERT INTO documents (id, patient_id, doc_date, kind, title, body_text, body_norm) VALUES ('d-svoboda-odber-2026-08-11', 'p-svoboda-2002', '2026-08-11', 'perf_eval', 'Záznam z kontroly — krevní odběr', 'Centrum sportovní medicíny z.s.
Pod altánem 67/352, 100 00 Praha 10 · tel +420 722 050 450 · info@centrumsportmed.cz
Záznam z kontroly — krevní odběr
Pacient:
Jakub Svoboda
Datum narození:
14.3.2002
Datum kontroly:
11.8.2026
Zapsal:
MUDr. Jana Procházková
Odběr: 11.8.2026, Laboratoře Modrý Kámen s.r.o.
Hodnocení
Kontrolní odběr nařízený při červnové prohlídce. S_Ferritin 18 µg/l pod dolní mezí, S_Železo 9,4 µmol/l pod dolní mezí,
saturace transferinu 14,8 % snížená. S_Kreatinkináza 6,80 µkat/l výrazně nad horní mezí i při deklarovaných dvou dnech
bez intenzivního tréninku. B_Hemoglobin 144 g/l — v rozmezí, ale nejnižší za dobu sledování.
Panel potvrzuje obavy z června: vyčerpané zásoby železa a známky svalového přetížení při klesající výkonnosti. Červnová
redukce objemu podle sdělení pacienta dodržena jen zčásti.
Doporučení
Zahájena denní perorální substituce železa. Přerušení intenzivního tréninku na 2 týdny, poté pouze pásma pod prvním
ventilačním prahem do kontroly. Kontrolní odběr a klinické vyšetření za 6 týdnů — podle výsledku zvážit rozšířené
vyšetření a úpravu ročního plánu. Nutná důsledná compliance.
MUDr. Jana Procházková
tělovýchovný lékař
Centrum sportovní medicíny z.s.
Ukázková data — smyšlený pacient i pracoviště, negenerováno z reálného vyšetření.
1 / 1', 'centrum sportovni mediciny z.s. pod altanem 67/352, 100 00 praha 10 · tel +420 722 050 450 · info@centrumsportmed.cz zaznam z kontroly — krevni odber pacient: jakub svoboda datum narozeni: 14.3.2002 datum kontroly: 11.8.2026 zapsal: mudr. jana prochazkova odber: 11.8.2026, laboratore modry kamen s.r.o. hodnoceni kontrolni odber narizeny pri cervnove prohlidce. s_ferritin 18 μg/l pod dolni mezi, s_zelezo 9,4 μmol/l pod dolni mezi, saturace transferinu 14,8 % snizena. s_kreatinkinaza 6,80 μkat/l vyrazne nad horni mezi i pri deklarovanych dvou dnech bez intenzivniho treninku. b_hemoglobin 144 g/l — v rozmezi, ale nejnizsi za dobu sledovani. panel potvrzuje obavy z cervna: vycerpane zasoby zeleza a znamky svaloveho pretizeni pri klesajici vykonnosti. cervnova redukce objemu podle sdeleni pacienta dodrzena jen zcasti. doporuceni zahajena denni peroralni substituce zeleza. preruseni intenzivniho treninku na 2 tydny, pote pouze pasma pod prvnim ventilacnim prahem do kontroly. kontrolni odber a klinicke vysetreni za 6 tydnu — podle vysledku zvazit rozsirene vysetreni a upravu rocniho planu. nutna dusledna compliance. mudr. jana prochazkova telovychovny lekar centrum sportovni mediciny z.s. ukazkova data — smysleny pacient i pracoviste, negenerovano z realneho vysetreni. 1 / 1');

